import * as React from 'react';
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import Container from '@mui/material/Container';
import Grid from '@mui/material/Grid';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesome';
import DesignServicesIcon from '@mui/icons-material/DesignServices';
import RocketLaunchIcon from '@mui/icons-material/RocketLaunch';
import InsightsIcon from '@mui/icons-material/Insights';

/**
 * Highlight card data
 * Each card represents a key service or feature
 */
const highlights = [
  {
    icon: <DesignServicesIcon />,
    title: 'Product Design',
    description: 'We create intuitive and engaging user experiences that solve real problems and delight users.',
  },
  {
    icon: <InsightsIcon />,
    title: 'Product Strategy',
    description: 'Our data-driven approach ensures your product aligns with market needs and business goals.',
  },
  {
    icon: <RocketLaunchIcon />,
    title: 'Product Development',
    description: 'We build scalable, high-performance solutions using cutting-edge technologies.',
  },
  {
    icon: <AutoAwesomeIcon />,
    title: 'Product Innovation',
    description: 'We help you stay ahead of the curve with innovative solutions that set new industry standards.',
  },
];

/**
 * HighlightCard Component
 * Individual card displaying a service or feature
 * @param {Object} props - Component props
 * @returns {JSX.Element} Card component
 */
function HighlightCard({ icon, title, description }) {
  return (
    <Card
      component="article"
      sx={{
        height: '100%',
        background: 'linear-gradient(145deg, rgba(30, 30, 30, 0.6), rgba(18, 18, 18, 0.8))',
        backdropFilter: 'blur(10px)',
        border: '1px solid',
        borderColor: 'divider',
        transition: 'all 0.3s ease-in-out',
        '&:hover': {
          transform: 'translateY(-4px)',
          boxShadow: (theme) => theme.shadows[8],
          borderColor: 'primary.main',
          '& .icon': {
            color: 'primary.main',
            transform: 'scale(1.1)',
          },
        },
      }}
    >
      <Stack
        spacing={2}
        sx={{
          p: 3,
          height: '100%',
        }}
      >
        <Box
          className="icon"
          sx={{
            color: 'text.secondary',
            transition: 'all 0.3s ease-in-out',
            '& > svg': {
              fontSize: 40,
            },
          }}
        >
          {icon}
        </Box>
        <Typography
          variant="h6"
          component="h3"
          sx={{
            fontWeight: 600,
            fontSize: { xs: '1.25rem', sm: '1.5rem' },
          }}
        >
          {title}
        </Typography>
        <Typography
          variant="body1"
          color="text.secondary"
          sx={{
            lineHeight: 1.75,
            fontSize: { xs: '0.875rem', sm: '1rem' },
          }}
        >
          {description}
        </Typography>
      </Stack>
    </Card>
  );
}

/**
 * Highlights Component
 * Displays a grid of service/feature highlights
 * @returns {JSX.Element} Highlights section
 */
export default function Highlights() {
  return (
    <section id="highlights" aria-label="Our Services">
      <Box
        sx={{
          pt: { xs: 4, sm: 12 },
          pb: { xs: 8, sm: 16 },
          bgcolor: 'transparent',
        }}
      >
        <Container>
          <Stack spacing={4}>
            <Typography
              component="h2"
              variant="h2"
              color="text.primary"
              textAlign="center"
              sx={{
                fontSize: { xs: '2rem', sm: '3rem' },
                fontWeight: 700,
                mb: { xs: 4, sm: 8 },
              }}
            >
              Our Services
            </Typography>
            <Grid
              container
              spacing={{ xs: 2, sm: 3 }}
              sx={{ maxWidth: 1200, mx: 'auto' }}
            >
              {highlights.map((highlight, index) => (
                <Grid item xs={12} sm={6} md={3} key={index}>
                  <HighlightCard {...highlight} />
                </Grid>
              ))}
            </Grid>
          </Stack>
        </Container>
      </Box>
    </section>
  );
}
